-- ADS Bin Cleaning test foundation. No production data or credentials.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','administrator','dispatcher','field_technician');
create type public.pickup_source as enum ('official_gis','official_address_lookup','staff_verified','customer_confirmed','unverified');
create type public.referral_status as enum ('code_entered','pending_signup','pending_first_service','pending_successful_payment','seven_day_hold','qualified','credit_issued','credit_applied','rejected','reversed');
create type public.visit_status as enum ('scheduled','assigned','en_route','arrived','before_photo_complete','cleaning_in_progress','after_photo_complete','bins_returned','completed','skipped','refused','weather_delayed','customer_not_ready');

create table public.user_profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, phone text, login_status text not null default 'active', is_test boolean not null default true, created_at timestamptz not null default now());
create table public.staff_roles (user_id uuid not null references public.user_profiles(id) on delete cascade, role public.app_role not null check(role <> 'customer'), granted_by uuid references public.user_profiles(id), granted_at timestamptz not null default now(), revoked_at timestamptz, primary key(user_id,role));
create table public.customers (id uuid primary key default gen_random_uuid(), user_id uuid unique references public.user_profiles(id), full_name text not null, email text not null, phone text, account_status text not null default 'test_pending', billing_address jsonb, is_residential boolean not null default true, is_test boolean not null default true, created_at timestamptz not null default now());
create table public.municipalities (id uuid primary key default gen_random_uuid(), name text not null unique, is_test boolean not null default true);
create table public.service_zones (id uuid primary key default gen_random_uuid(), municipality_id uuid references public.municipalities(id), name text not null, active boolean not null default false, is_test boolean not null default true);
create table public.service_addresses (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id) on delete cascade, municipality_id uuid references public.municipalities(id), line1 text not null, line2 text, city text not null, region text not null, postal_code text not null, normalized_address_hash text not null, latitude numeric(9,6), longitude numeric(9,6), coordinates_validated_at timestamptz, preferred_return_location text, access_instructions text, gate_information text, animal_warning text, accessibility_notes text, is_test boolean not null default true, created_at timestamptz not null default now(), unique(normalized_address_hash));
create table public.customer_contact_preferences (customer_id uuid primary key references public.customers(id) on delete cascade, email_allowed boolean not null default false, sms_allowed boolean not null default false, phone_allowed boolean not null default false, updated_at timestamptz not null default now());
create table public.bins (id uuid primary key default gen_random_uuid(), service_address_id uuid not null references public.service_addresses(id) on delete cascade, identifier text, description text, active boolean not null default true, dirty_this_visit boolean not null default false);
create table public.service_plans (id text primary key, display_name text not null, current_version text not null, status text not null check(status in ('active','future')), public_visible boolean not null, referral_eligible boolean not null);
create table public.service_plan_versions (id uuid primary key default gen_random_uuid(), plan_id text not null references public.service_plans(id), catalog_version text not null, charge_type text not null, interval_months integer, base_price_cents integer, additional_bin_price_cents integer, bins_included integer, effective_at timestamptz not null, retired_at timestamptz, unique(plan_id,catalog_version));
create table public.subscriptions (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), service_plan_version_id uuid not null references public.service_plan_versions(id), payment_status text not null default 'not_configured', subscription_status text not null default 'test_only', service_status text not null default 'pending', started_at timestamptz, ended_at timestamptz);
create table public.trash_pickup_schedules (id uuid primary key default gen_random_uuid(), service_address_id uuid not null references public.service_addresses(id), weekday smallint check(weekday between 0 and 6), source public.pickup_source not null default 'unverified', verification_status text not null default 'unverified', customer_reported_weekday smallint, official_weekday smallint, effective_from date not null, effective_to date, holiday_shift_days integer not null default 0 check(holiday_shift_days >= 0), holiday_shift_status text not null default 'none');
create table public.cleaning_day_assignments (id uuid primary key default gen_random_uuid(), pickup_schedule_id uuid not null references public.trash_pickup_schedules(id), normal_weekday smallint not null check(normal_weekday between 0 and 6), pickup_date date, adjusted_pickup_date date, cleaning_date date, staff_verified_by uuid references public.user_profiles(id), review_status text not null default 'pending', check(cleaning_date is null or adjusted_pickup_date is null or cleaning_date = adjusted_pickup_date + 1));
create table public.routes (id uuid primary key default gen_random_uuid(), service_zone_id uuid references public.service_zones(id), route_date date not null, status text not null default 'draft', dispatcher_id uuid references public.user_profiles(id), technician_id uuid references public.user_profiles(id), capacity integer, is_test boolean not null default true);
create table public.route_stops (id uuid primary key default gen_random_uuid(), route_id uuid not null references public.routes(id) on delete cascade, service_address_id uuid not null references public.service_addresses(id), stop_order integer, scheduling_status text not null default 'planned', preparation_information text, unique(route_id,service_address_id));
create table public.service_visits (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), route_stop_id uuid references public.route_stops(id), assigned_technician_id uuid references public.user_profiles(id), scheduled_for timestamptz, status public.visit_status not null default 'scheduled', cleaning_confirmed boolean not null default false, bins_returned boolean not null default false, completed_at timestamptz, is_test boolean not null default true);
create table public.visit_status_history (id uuid primary key default gen_random_uuid(), service_visit_id uuid not null references public.service_visits(id) on delete cascade, from_status public.visit_status, to_status public.visit_status not null, actor_id uuid references public.user_profiles(id), reason text, created_at timestamptz not null default now());
create table public.visit_photographs (id uuid primary key default gen_random_uuid(), service_visit_id uuid not null references public.service_visits(id) on delete cascade, kind text not null check(kind in ('before','after')), storage_path text not null, uploaded_by uuid not null references public.user_profiles(id), created_at timestamptz not null default now());
create table public.service_exceptions (id uuid primary key default gen_random_uuid(), service_visit_id uuid not null references public.service_visits(id), exception_type text not null, details text not null, authorized_return_exception boolean not null default false, status text not null default 'open', recorded_by uuid references public.user_profiles(id), created_at timestamptz not null default now());
create table public.referral_codes (id uuid primary key default gen_random_uuid(), customer_id uuid not null unique references public.customers(id), code text not null unique default ('ADS-' || upper(encode(gen_random_bytes(8),'hex'))), share_url text generated always as ('https://example.test/bin-cleaning/signup?ref=' || code) stored, active boolean not null default true, created_at timestamptz not null default now());
create table public.referral_relationships (id uuid primary key default gen_random_uuid(), referral_code_id uuid not null references public.referral_codes(id), referrer_customer_id uuid not null references public.customers(id), referred_customer_id uuid not null unique references public.customers(id), referred_address_hash text not null, status public.referral_status not null default 'code_entered', lookback_started_at timestamptz not null default (now() - interval '12 months'), hold_until timestamptz, rejection_reason text, created_at timestamptz not null default now(), check(referrer_customer_id <> referred_customer_id));
create table public.referral_status_history (id uuid primary key default gen_random_uuid(), referral_relationship_id uuid not null references public.referral_relationships(id), from_status public.referral_status, to_status public.referral_status not null, actor_id uuid references public.user_profiles(id), reason text, created_at timestamptz not null default now());
create table public.referral_credits (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), referral_relationship_id uuid not null references public.referral_relationships(id), amount_cents integer not null check(amount_cents > 0), remaining_cents integer not null check(remaining_cents >= 0), status text not null check(status in ('issued','partially_applied','applied','reversed')), earned_at timestamptz not null, expires_at timestamptz not null, check(expires_at = earned_at + interval '12 months'), check(remaining_cents <= amount_cents));
create table public.customer_notes (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id), body text not null, visibility text not null default 'staff_only', created_by uuid not null references public.user_profiles(id), created_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references public.user_profiles(id), action text not null, entity_table text not null, entity_id uuid, before_data jsonb, after_data jsonb, reason text, created_at timestamptz not null default now());

create or replace function public.has_role(requested public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from staff_roles where user_id=auth.uid() and role=requested and revoked_at is null) $$;
create or replace function public.is_staff() returns boolean language sql stable as $$ select public.has_role('administrator') or public.has_role('dispatcher') or public.has_role('field_technician') $$;
create or replace function public.owns_customer(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from customers where id=target and user_id=auth.uid()) $$;
create or replace function public.customer_for_address(target uuid) returns uuid language sql stable security definer set search_path=public as $$ select customer_id from service_addresses where id=target $$;
create or replace function public.visit_is_assigned(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from service_visits where id=target and assigned_technician_id=auth.uid()) $$;
create or replace function public.validate_visit_completion() returns trigger language plpgsql as $$ begin if new.status='completed' and (not new.cleaning_confirmed or not exists(select 1 from visit_photographs p where p.service_visit_id=new.id and p.kind='before') or not exists(select 1 from visit_photographs p where p.service_visit_id=new.id and p.kind='after') or (not new.bins_returned and not exists(select 1 from service_exceptions e where e.service_visit_id=new.id and e.authorized_return_exception and e.status='authorized'))) then raise exception 'Completion requires before/after photos, cleaning, and bin return or authorized exception'; end if; return new; end $$;
create constraint trigger enforce_visit_completion after insert or update on public.service_visits deferrable initially deferred for each row execute function public.validate_visit_completion();

-- Default deny: every application table uses RLS. Policies below grant only explicit rows/actions.
do $$ declare t text; begin foreach t in array array['user_profiles','staff_roles','customers','municipalities','service_zones','service_addresses','customer_contact_preferences','bins','service_plans','service_plan_versions','subscriptions','trash_pickup_schedules','cleaning_day_assignments','routes','route_stops','service_visits','visit_status_history','visit_photographs','service_exceptions','referral_codes','referral_relationships','referral_status_history','referral_credits','customer_notes','audit_events'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
-- Own profile/customer data.
create policy profile_own_read on public.user_profiles for select using(id=auth.uid() or public.has_role('administrator'));
create policy profile_own_update on public.user_profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy admin_staff_roles on public.staff_roles for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy customer_own_read on public.customers for select using(user_id=auth.uid() or public.has_role('administrator') or public.has_role('dispatcher'));
create policy customer_own_update on public.customers for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy staff_manage_customers on public.customers for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy address_customer_read on public.service_addresses for select using(public.owns_customer(customer_id) or public.has_role('administrator') or public.has_role('dispatcher') or exists(select 1 from service_visits v where v.assigned_technician_id=auth.uid() and v.customer_id=service_addresses.customer_id));
create policy address_staff_manage on public.service_addresses for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy contact_owner on public.customer_contact_preferences for all using(public.owns_customer(customer_id)) with check(public.owns_customer(customer_id));
create policy contact_staff on public.customer_contact_preferences for select using(public.has_role('administrator') or public.has_role('dispatcher'));
create policy bins_owner_read on public.bins for select using(public.owns_customer(public.customer_for_address(service_address_id)) or public.has_role('administrator') or public.has_role('dispatcher') or exists(select 1 from service_visits v join service_addresses a on a.customer_id=v.customer_id where a.id=bins.service_address_id and v.assigned_technician_id=auth.uid()));
create policy bins_owner_update on public.bins for update using(public.owns_customer(public.customer_for_address(service_address_id))) with check(public.owns_customer(public.customer_for_address(service_address_id)));
create policy bins_staff_manage on public.bins for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy catalog_authenticated_read on public.service_plans for select to authenticated using(true);
create policy catalog_versions_authenticated_read on public.service_plan_versions for select to authenticated using(true);
create policy catalog_admin_manage on public.service_plans for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy catalog_versions_admin_manage on public.service_plan_versions for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy subscriptions_owner_read on public.subscriptions for select using(public.owns_customer(customer_id) or public.has_role('administrator'));
create policy subscriptions_admin_manage on public.subscriptions for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy visits_owner_read on public.service_visits for select using(public.owns_customer(customer_id) or public.has_role('administrator') or public.has_role('dispatcher') or assigned_technician_id=auth.uid());
create policy visits_staff_manage on public.service_visits for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy visits_tech_update on public.service_visits for update using(assigned_technician_id=auth.uid()) with check(assigned_technician_id=auth.uid());
create policy photos_owner_read on public.visit_photographs for select using(public.visit_is_assigned(service_visit_id) or exists(select 1 from service_visits v where v.id=service_visit_id and public.owns_customer(v.customer_id)) or public.has_role('administrator') or public.has_role('dispatcher'));
create policy photos_tech_insert on public.visit_photographs for insert with check(public.visit_is_assigned(service_visit_id) and uploaded_by=auth.uid());
create policy photos_staff_manage on public.visit_photographs for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy referrals_codes_owner on public.referral_codes for select using(public.owns_customer(customer_id) or public.has_role('administrator'));
create policy referrals_rel_owner on public.referral_relationships for select using(public.owns_customer(referrer_customer_id) or public.owns_customer(referred_customer_id) or public.has_role('administrator'));
create policy referral_credits_owner on public.referral_credits for select using(public.owns_customer(customer_id) or public.has_role('administrator'));
create policy referrals_admin_manage on public.referral_relationships for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy credits_admin_manage on public.referral_credits for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy notes_staff on public.customer_notes for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy audit_admin_read on public.audit_events for select using(public.has_role('administrator'));
create policy audit_staff_insert on public.audit_events for insert with check(actor_id=auth.uid() and public.is_staff());
-- Dispatcher route control; technician sees only assigned routes/stops. Administrator controls all operations.
create policy route_admin_dispatcher on public.routes for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy route_tech_read on public.routes for select using(technician_id=auth.uid());
create policy stops_admin_dispatcher on public.route_stops for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy stops_tech_read on public.route_stops for select using(exists(select 1 from routes r where r.id=route_id and r.technician_id=auth.uid()));
-- Operational supporting tables: customers see their schedule/history; dispatcher/admin manage; assigned tech sees visit details.
create policy pickup_owner_staff on public.trash_pickup_schedules for select using(public.owns_customer(public.customer_for_address(service_address_id)) or public.has_role('administrator') or public.has_role('dispatcher') or exists(select 1 from service_visits v where v.customer_id=public.customer_for_address(service_address_id) and v.assigned_technician_id=auth.uid()));
create policy pickup_staff_manage on public.trash_pickup_schedules for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy cleaning_owner_staff on public.cleaning_day_assignments for select using(exists(select 1 from trash_pickup_schedules p where p.id=pickup_schedule_id and (public.owns_customer(public.customer_for_address(p.service_address_id)) or public.is_staff())));
create policy cleaning_dispatch_manage on public.cleaning_day_assignments for all using(public.has_role('administrator') or public.has_role('dispatcher')) with check(public.has_role('administrator') or public.has_role('dispatcher'));
create policy visit_history_visible on public.visit_status_history for select using(public.visit_is_assigned(service_visit_id) or exists(select 1 from service_visits v where v.id=service_visit_id and public.owns_customer(v.customer_id)) or public.has_role('administrator') or public.has_role('dispatcher'));
create policy visit_history_staff_insert on public.visit_status_history for insert with check((public.visit_is_assigned(service_visit_id) and actor_id=auth.uid()) or public.has_role('administrator') or public.has_role('dispatcher'));
create policy exceptions_visible on public.service_exceptions for select using(public.visit_is_assigned(service_visit_id) or exists(select 1 from service_visits v where v.id=service_visit_id and public.owns_customer(v.customer_id)) or public.has_role('administrator') or public.has_role('dispatcher'));
create policy exceptions_staff_manage on public.service_exceptions for all using(public.has_role('administrator') or public.has_role('dispatcher') or public.visit_is_assigned(service_visit_id)) with check(public.has_role('administrator') or public.has_role('dispatcher') or (public.visit_is_assigned(service_visit_id) and recorded_by=auth.uid()));
create policy municipalities_read on public.municipalities for select to authenticated using(true);
create policy municipalities_admin on public.municipalities for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy zones_staff_read on public.service_zones for select using(public.is_staff());
create policy zones_admin on public.service_zones for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
create policy referral_history_owner on public.referral_status_history for select using(exists(select 1 from referral_relationships r where r.id=referral_relationship_id and (public.owns_customer(r.referrer_customer_id) or public.owns_customer(r.referred_customer_id))) or public.has_role('administrator'));
create policy referral_history_admin on public.referral_status_history for all using(public.has_role('administrator')) with check(public.has_role('administrator'));
